  "name": "reweight_gap_linear_mad",
  "intuition": "Weights all winner-loser pairs by the linear objective gap scaled inversely by instance MAD, ensuring stable instance-conditioned pair weighting that preserves all pairs topology and avoids failure from overcomplex conditioning.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
