    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    obj_mad = feature_cache['instance_obj_mad']\n    eps = 1e-6\n    # Construct mask for winner-loser pairs\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Compute objective gap for pairs\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Scale gap by instance MAD for conditioning\n    denom = obj_mad[b_idx].clamp_min(eps)\n    weight = gap / denom\n    # Clamp weights to [0.25, 4.0] for stability\n    weight = weight.clamp_min(0.0).clamp(0.25, 4.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweight_gap_linear_mad', 'weight_family': 'gap_linear'})"
