  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    eps = 1e-6\n    instance_obj_range = feature_cache.get('instance_obj_range', None)\n    instance_log_prob_range = feature_cache.get('instance_log_prob_range', None)\n    obj_scale = instance_obj_range[b_idx].clamp_min(eps) if instance_obj_range is not None else torch.ones_like(gap)\n    logp_scale = instance_log_prob_range[b_idx].clamp_min(eps) if instance_log_prob_range is not None else torch.ones_like(gap)\n    scaled_gap = gap / obj_scale\n    # Weight linearly by scaled gap modulated by inverse log-prob range (to emphasize instances with tighter log-prob spread)\n    raw = scaled_gap * (1.0 / logp_scale)\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    clamp_lo = float(extra.get('clamp_lo', 0.25))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n"
