  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    eps = 1e-6\n    instance_obj_scale = feature_cache['instance_obj_mad'].clamp_min(eps)\n    gap_scaled = gap / instance_obj_scale[b_idx]\n    # Bandpass parameters (tunable via extra)\n    tau_low = float(extra.get('tau_low', 0.5))\n    tau_high = float(extra.get('tau_high', 2.0))\n    weight = (gap_scaled - tau_low).clamp(min=0) * (tau_high - gap_scaled).clamp(min=0)\n    # Normalize by squared band width to keep scale consistent\n    band_width = tau_high - tau_low\n    weight = weight / (band_width * band_width + eps)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = torch.nan_to_num(weight, nan=0.0, posinf=0.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n"
